def inr_format(amount):
    if amount == 0:
        return '0'
    str_amount = str(amount)
    length = len(str_amount)
    if length <= 3:
        return str_amount
    formatted_amount = str_amount[-3:]  # Keep the last three digits
    for i in range(length-3, 0, -2):
        formatted_amount = str_amount[i-2:i] + ',' + formatted_amount
    return formatted_amount

